// clueQ(group, withWhy) -> generator. Wrong options carry a trap message = what that category really means.
const clueQ=(g,w)=>n=>{const it=pick(g.it),c=g.c[it[1]],ans=c[0];
  const ws=g.c.filter(x=>x!==c).map(x=>[x[0],'اختيارك «'+x[0]+'» معناه: '+x[1]+'. هل هذا ما تصفه الكلمات؟']).concat(n>3?(g.x||[]):[]);
  const q=mk(g.q.replace('#',it[0]),ans,ws,['اقرئي الكلمات المفتاحية جيداً واسألي: إلى أي فكرة تشير؟','«'+ans+'» = '+c[1]],n);
  if(!w)return q;const ow=shuffle(g.c.filter(x=>x!==c)).slice(0,2).map(x=>x[1]);
  return why(q,['ولماذا «'+ans+'»؟',c[1],ow,'تذكّري: '+ans+' = '+c[1]+'.']);};

