// ---------- light / dark ----------
(function(){
  const KEY='salma_theme',root=document.documentElement;
  let t=null;try{t=localStorage.getItem(KEY);}catch(e){}
  if(!t)t=(window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches)?'dk':'lt';
  const apply=()=>{root.classList.toggle('dk',t==='dk');const b=document.getElementById('thm');if(b)b.textContent=t==='dk'?'☀️ فاتح':'🌙 داكن';
    const m=document.querySelector('meta[name=color-scheme]')||document.head.appendChild(Object.assign(document.createElement('meta'),{name:'color-scheme'}));m.content=t==='dk'?'dark':'light';};
  const h=document.querySelector('header');
  if(h){const b=document.createElement('button');b.id='thm';b.type='button';b.setAttribute('aria-label','تبديل الوضع الفاتح والداكن');
    b.onclick=()=>{t=t==='dk'?'lt':'dk';try{localStorage.setItem(KEY,t);}catch(e){}apply();};h.appendChild(b);}
  apply();
})();

